// Vendor of a universal MAC from the reduced OUI database: oui.tsv, one "aabbcc<TAB>name"
// line per IEEE MA-L prefix, versioned and generated by hand by scripts/update-oui.js.
// Loaded on the first lookup; no network request at run time. Missing file: no vendor.
import fs from 'node:fs'
import { fileURLToPath } from 'node:url'
import { isLocal, normalizeMac } from '../net/mac.js'

export const OUI_FILE = fileURLToPath(new URL('./oui.tsv', import.meta.url))

function load(file) {
  const map = new Map()
  let text = ''
  try {
    text = fs.readFileSync(file, 'utf8')
  } catch {
    return map
  }
  for (const line of text.split('\n')) {
    if (line[6] === '\t' && /^[0-9a-f]{6}$/.test(line.slice(0, 6))) map.set(line.slice(0, 6), line.slice(7))
  }
  return map
}

// lookup on a given file (tests): universal MAC (U/L bit at 0) → vendor name, or null; a
// local MAC has none
export function createOui(file = OUI_FILE) {
  let table = null
  return mac => {
    const m = normalizeMac(mac)
    if (!m || isLocal(m)) return null
    table ??= load(file)
    return table.get(m.slice(0, 8).replace(/:/g, '')) ?? null
  }
}

export const ouiOf = createOui()
